#!/usr/bin/env python3
"""Rebuild the CSX-148_Q2 numeric ground truth."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-148_Q2"
EVENT_ID = "CSX-148"
TARGET_FAMILY = "free_state_storm_impact_threshold_ledger"
PACKAGE_RELATIVE_PATH = f"event_packages/standard_event_packages/packages/{EVENT_ID}"
INPUT_RECORDS = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_anchor_report_National_government_statement_citing_SAWS_severe_weather.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_December_2023_Free_State_severe_thunderstorms_and_hail.json",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        cleaned = " ".join(data.split())
        if cleaned:
            self.parts.append(cleaned)

    @property
    def text(self) -> str:
        return " ".join(self.parts)


def find_repo_root(start: Path) -> Path:
    for probe in [start, *start.parents]:
        if (probe / PACKAGE_RELATIVE_PATH).is_dir():
            return probe
    raise FileNotFoundError(f"Could not locate {PACKAGE_RELATIVE_PATH}")


def load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def html_text(path: Path) -> str:
    parser = TextExtractor()
    parser.feed(path.read_text(encoding="utf-8", errors="ignore"))
    return parser.text


def first_int(pattern: str, text: str, flags: int = re.IGNORECASE | re.DOTALL) -> int:
    match = re.search(pattern, text, flags)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1))


def present(pattern: str, text: str) -> bool:
    return bool(re.search(pattern, text, re.IGNORECASE | re.DOTALL))


def build_output() -> dict[str, Any]:
    task_dir = Path(__file__).resolve().parent
    package_dir = find_repo_root(task_dir) / PACKAGE_RELATIVE_PATH

    event_meta = load_json(package_dir / "metadata/event.json")
    anchor = load_json(
        package_dir
        / "data/event_reports/event_reports_003_Locked_event_anchor_December_2023_Free_State_severe_thunderstorms_and_hail.json"
    )
    report = html_text(
        package_dir
        / "data/event_reports/event_reports_001_Locked_anchor_report_National_government_statement_citing_SAWS_severe_weather.html"
    )

    fatalities = 1 if present(r"lost his life|fatally injured|loss of a life", report) else 0
    hospital_admissions = first_int(r"confirmed that\s+(\d+)\s+patients were admitted", report)
    bloemfontein_houses = first_int(r"roofs of sixteen\s*\((\d+)\)\s+houses.*?Bloemfontein", report)
    dewetsdorp_houses = first_int(r"Dewetsdorp.*?(\d+)\s+houses", report)
    madikgetla_houses = 2 if present(r"roofs of two houses in Madikgetla", report) else 0
    bohlokong_houses = first_int(r"fifty\s*\((\d+)\)\s+residential houses in Bohlokong", report)
    residential_shacks = first_int(r"while\s+(\d+)\s+residential shacks", report)

    damaged_stadiums = 2 if present(r"two stadiums", report) else 0
    damaged_church = 1 if present(r"a church and a school", report) else 0
    damaged_school = 1 if present(r"a church and a school", report) else 0
    cbd_roof_asset = 1 if present(r"roof of building in Mangaung CBD was blown off", report) else 0

    utility_substations = first_int(r"Lightning struck seven\s*\((\d+)\)", report)
    power_bonus = 20 if present(r"loss of power supply|electrical supply infrastructure.*affected", report) else 0

    pathway_flags = {
        "street_or_road_flooding": present(r"Street and Road Flooding", report),
        "residential_flooding": present(r"Residential Flooding", report),
        "crop_damage": present(r"destruction of crop", report),
        "vegetation_or_tree_damage": present(r"Tree \(Vegetation\) Damage|uprooting and falling of trees", report),
    }

    reported_houses = bloemfontein_houses + dewetsdorp_houses + madikgetla_houses + bohlokong_houses
    residential_structures = reported_houses + residential_shacks
    public_cbd_assets = damaged_stadiums + damaged_church + damaged_school + cbd_roof_asset
    qualitative_pathways = sum(1 for value in pathway_flags.values() if value)

    shelter_index = (
        100 * fatalities
        + 25 * hospital_admissions
        + residential_structures
        + 10 * public_cbd_assets
    )
    utility_index = 15 * utility_substations + power_bonus
    ratio = round(shelter_index / utility_index, 3)
    threshold_margin = shelter_index - 4 * utility_index
    threshold_met = (
        shelter_index >= 4 * utility_index
        and residential_structures >= 300
        and public_cbd_assets >= 5
    )
    answer_label = "shelter_utility_threshold_met" if threshold_met else "threshold_not_met"

    counts = {
        "fatalities": fatalities,
        "hospital_admissions": hospital_admissions,
        "reported_houses": reported_houses,
        "residential_structures": residential_structures,
        "public_cbd_assets": public_cbd_assets,
        "utility_substations": utility_substations,
        "qualitative_pathways": qualitative_pathways,
    }
    indices = {
        "shelter_index": shelter_index,
        "utility_index": utility_index,
        "shelter_utility_ratio": ratio,
        "threshold_margin": threshold_margin,
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final threshold ledger",
                "points": 3,
                "description": "Reports threshold_met = true with class_label = shelter_utility_threshold_met and no contradictory label.",
                "partial_credit": "Award 2 points for the correct boolean without the label, or 1 point for a threshold-met conclusion with incomplete JSON.",
            },
            {
                "name": "Core report counts",
                "points": 4,
                "description": "Extracts 1 fatality, 3 hospital admissions, 7 utility substations, and the four place-specific house counts.",
                "partial_credit": "Award 1 point per correctly extracted group; do not award credit for values invented outside the record.",
            },
            {
                "name": "Residential and public asset arithmetic",
                "points": 3,
                "description": "Computes reported_houses = 292, residential_structures = 342, and public_cbd_assets = 5.",
                "partial_credit": "Award 1 point for each correct derived value.",
            },
            {
                "name": "Utility and qualitative pathway ledger",
                "points": 3,
                "description": "Uses 7 lightning-struck substations, applies the power-supply bonus, and counts four qualitative pathways.",
                "partial_credit": "Award 1 point for the substations, 1 point for applying or explaining the bonus, and 1 point for the four-pathway count.",
            },
            {
                "name": "Index and margin arithmetic",
                "points": 4,
                "description": "Computes shelter_index = 567, utility_index = 125, shelter_utility_ratio = 4.536, and threshold_margin = 67.",
                "partial_credit": "Award 1 point for each correct computed value, allowing a ratio tolerance of 0.001.",
            },
            {
                "name": "Three-part threshold test",
                "points": 2,
                "description": "Checks all three required inequalities: 567 >= 500, 342 >= 300, and 5 >= 5.",
                "partial_credit": "Award 1 point for checking only the shelter-utility inequality or for missing one of the two minimum-count tests.",
            },
            {
                "name": "Compact output discipline",
                "points": 1,
                "description": "Returns only the requested compact JSON and does not add exact hail size, wind gust, flood depth, outage duration, or agricultural area values.",
                "partial_credit": "Award 0.5 points for a correct ledger with extra prose; award no credit for adding exact values outside the requested ledger.",
            },
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "event": {
            "name": event_meta["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "date": anchor["temporal_window"]["start_date"],
            "location": anchor["spatial_window"]["location_text"],
        },
        "primary_gt": {
            "answer": answer_label,
            "class_label": answer_label,
            "counts": counts,
            "indices": indices,
            "threshold_met": threshold_met,
        },
        "formula_rules": {
            "reported_houses": "16 + 24 + 2 + 250",
            "residential_structures": "reported_houses + 50",
            "public_cbd_assets": "2 + 1 + 1 + 1",
            "shelter_index": "100*fatalities + 25*hospital_admissions + residential_structures + 10*public_cbd_assets",
            "utility_index": "15*utility_substations + power_bonus",
            "threshold_met": "shelter_index >= 4*utility_index and residential_structures >= 300 and public_cbd_assets >= 5",
        },
        "supporting_values": {
            "component_house_counts": {
                "bloemfontein": bloemfontein_houses,
                "dewetsdorp": dewetsdorp_houses,
                "madikgetla": madikgetla_houses,
                "bohlokong": bohlokong_houses,
                "bohlokong_shacks": residential_shacks,
            },
            "component_public_cbd_assets": {
                "stadiums": damaged_stadiums,
                "church": damaged_church,
                "school": damaged_school,
                "mangaung_cbd_roof_asset": cbd_roof_asset,
            },
            "pathway_flags": pathway_flags,
            "power_bonus": power_bonus,
        },
        "numeric_tolerances": {
            "integer_fields": 0,
            "ratio": 0.001,
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": INPUT_RECORDS,
        },
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    output = build_output()
    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
